import unicodedata
def ext2(path,start):
    t=open(path).read();pos=[];plain=''
    for n,c in enumerate(t):
        if unicodedata.category(c)=='Mn' or c in '\u200f\u200e\u0640': continue
        plain+=c;pos.append(n)
    k=plain.index(start)
    i=pos[k]
    j=t.index('\u200f"\u200f',i)
    return t[i:j].strip()
HAD=ext2('/tmp/h2/b757.txt','إذا قمت إلى الصلاة فكبر')
print(HAD)
